 async void Act(Action action,string success,ProfileCard card=null){
  if(busy)return;busy=true;if(card!=null)card.Loading(true);
  try{await Task.Run(action);toast.Show(String.IsNullOrEmpty(Engine.LastLaunchNotice)?success:Engine.LastLaunchNotice);Engine.LastLaunchNotice="";}catch(Exception ex){Engine.Log(ex.ToString());ShowManager();MessageBox.Show(window,ex.Message,"Dual Steam",MessageBoxButton.OK,MessageBoxImage.Information);}
  finally{busy=false;if(card!=null)card.EndLoading();}await Refresh();
 }
 async Task Refresh(){
  if(refreshing||render||removingSetup)return;refreshing=true;
  try{
   var main=await Task.Run(()=>Engine.MainSteam());
   NativeStatus status=Engine.Current==null?new NativeStatus():await Task.Run(()=>Engine.Status());Process[] second=(status.RootIds??new int[0]).Select(id=>{try{return Process.GetProcessById(id);}catch{return null;}}).Where(p=>p!=null).ToArray();
   if(mainCard!=null){mainCard.Update(main);mainCard.Quit.IsEnabled=false;secondCard.Update(second,Engine.Current!=null);secondCard.Open.IsEnabled=!busy;secondCard.Quit.IsEnabled=!busy&&second.Length>0;}
   if(medalStatus!=null)medalStatus.Text=MedalCompatibility.Status;
   if(secondCard!=null&&second.Length>0&&!status.WindowReady){secondCard.Pill.Set("Starting","warning","Second Steam");secondCard.Usage.Text=status.Error??"Process running · waiting for its interface";}
   if(processMain!=null){processMain.Update(await Task.Run(()=>PerformanceSnapshot.Main()));processSecond.Update(PerformanceSnapshot.Second(status));}
   if(tray!=null)tray.Update(second.Length>0);
  }catch(Exception ex){if(secondCard!=null){secondCard.Pill.Set("Unavailable","warning","Second Steam");secondCard.ToolTip=ex.Message;}}
  finally{refreshing=false;}
 }
