 void Configure(){
  if(Engine.Current==null){BeginSetup();return;}
  string steam=Engine.Current==null?Engine.DetectSteam():Engine.Current.MainSteam;
  if(steam.Length==0){var dialog=new Microsoft.Win32.OpenFileDialog{Title="Locate main steam.exe",Filter="Steam client|steam.exe"};if(dialog.ShowDialog()!=true)return;steam=dialog.FileName;}
  Act(()=>{if(Engine.Current!=null&&Engine.SecondSteam().Length>0)throw new Exception("Quit Second Steam before repairing setup.");Engine.Setup(steam);LibraryCatalog.Sync(Engine.Current);},"Setup and library list updated.");
 }
 void SyncLibraries(){
  if(Engine.Current==null){Configure();return;}
  Act(()=>{if(Engine.SecondSteam().Length>0)throw new Exception("Quit Second Steam before refreshing libraries.");LibraryCatalog.Sync(Engine.Current);},"Game libraries detected. Open Second Steam.");
 }
