 protected override void OnStartup(StartupEventArgs e){base.OnStartup(e);options=e.Args;render=options.Contains("--render");Directory.CreateDirectory(Path.Combine(Engine.Home,"Verification"));Preferences.Load();string mode="Dark";string themeFile=Path.Combine(Engine.Home,@"Data\theme.txt");if(File.Exists(themeFile))mode=File.ReadAllText(themeFile).Trim();if(render&&options.Length>2)mode=options[2];Theme.Apply(mode);Theme.InitStyles();Engine.Load();BuildShell();MainWindow=window;if(render&&options.Length>4){window.Width=Double.Parse(options[3]);window.Height=Double.Parse(options[4]);}ShowPage(render&&options.Length>1?options[1]:"Profiles");bool silent=!render&&(options.Contains("--second")||options.Contains("--background"));if(silent){window.ShowActivated=false;window.Opacity=0;}window.Show();if(silent){window.Hide();window.Opacity=1;window.ShowActivated=true;}Responsive();
