 [STAThread]public static int Main(string[] args){
  DualSteamNative.SteamTaskbarIdentity.SetManagerIdentity();
  if(!Environment.Is64BitOperatingSystem||Environment.OSVersion.Version.Major<10){MessageBox.Show("Dual Steam requires Windows 10 or Windows 11, 64-bit, with .NET Framework 4.8.","Unsupported Windows version");return 1;}
  if(!args.Contains("--render")&&!DualSteam.UpdatePackage.RuntimeFilesPresent(Engine.Home)){MessageBox.Show("Extract the entire Dual Steam ZIP into a writable folder before opening the app. Keep its files together.","Complete app folder required");return 1;}
  if(args.Contains("--medal-compat")){try{Engine.Load();string mode=args.Last();if(mode=="enable")MedalCompatibility.Enable();else if(mode=="restore")MedalCompatibility.Restore();else if(mode!="status")throw new Exception("Choose enable, restore or status");File.WriteAllText(Path.Combine(Engine.Home,@"Verification\medal-compat-status.txt"),MedalCompatibility.Status);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(Engine.Home,@"Verification\medal-compat-status.txt"),ex.ToString());return 1;}}
  if(args.Contains("--status")){try{Engine.Load();File.WriteAllText(Path.Combine(Engine.Home,@"Verification\status.txt"),"Main="+String.Join(",",Engine.MainSteam().Select(p=>p.Id))+"; Second="+(Engine.Current==null?"not configured":String.Join(",",Engine.SecondPids())));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(Engine.Home,@"Verification\status.txt"),ex.ToString());return 1;}}
  if(args.Contains("--sync")){try{Engine.Load();if(Engine.SecondSteam().Length>0)throw new Exception("Quit Second Steam first.");LibraryCatalog.Sync(Engine.Current);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(Engine.Home,@"Verification\sync-error.txt"),ex.ToString());return 1;}}
  if(args.Contains("--render")){new App().Run();return 0;}
  bool created;using(var mutex=new Mutex(true,"Local\\WrakeebDualSteam",out created)){if(!created){try{foreach(var manager in Process.GetProcessesByName("Dual Steam"))if(Engine.Image(manager).Equals(Path.Combine(Engine.Home,"Dual Steam.exe"),StringComparison.OrdinalIgnoreCase))Engine.AllowForeground(manager.Id);using(var signal=EventWaitHandle.OpenExisting(args.Contains("--second")?"Local\\WrakeebDualSteamSecond":"Local\\WrakeebDualSteamShow"))signal.Set();return 0;}catch{MessageBox.Show("Dual Steam is still starting. Try its shortcut again in a moment.");return 1;}}using(showSignal=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\WrakeebDualSteamShow"))using(secondSignal=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\WrakeebDualSteamSecond")){try{new App().Run();return 0;}catch(Exception ex){Engine.Log(ex.ToString());MessageBox.Show(ex.Message,"Dual Steam");return 1;}}}
 }
}
